import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, uniform } from 'three/tsl';

export default function createNode(config, ctx) {
  const { THREE } = ctx;

  // Create a billboard plane with atlas region aspect ratio
  // Source rect: 512x320 → aspect 1.6:1
  const aspectRatio = 512 / 320;
  const geometry = new THREE.PlaneGeometry(aspectRatio * 1.2, 1.2);

  // Load the sprite texture
  const texturePromise = ctx.textureLoader.loadTexture(config.imageUrl);

  // Create material with TSL nodes
  const material = new MeshBasicNodeMaterial({
    transparent: true,
    side: THREE.DoubleSide,
  });

  // UV offset for atlas region (0, 0, 512, 320) in a larger atlas
  // Assuming the atlas source rect maps directly to this texture
  // UV bounds: x [0, 512/atlasWidth], y [0, 320/atlasHeight]
  // For a 512x320 texture, we use full UV range [0,1] x [0,1]
  const uvNode = uv();
  material.colorNode = uniform(new THREE.Texture()).mul(uvNode);

  // Apply texture once loaded
  texturePromise.then((texture) => {
    material.colorNode = uniform(texture);
    material.needsUpdate = true;
  });

  const mesh = new THREE.Mesh(geometry, material);
  mesh.castShadow = true;
  mesh.receiveShadow = true;

  // Build group with proper scene positioning
  const group = new THREE.Group();
  group.add(mesh);

  // Store cleanup routine
  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    texturePromise.then((texture) => {
      texture.dispose();
    }).catch(() => {});
  };

  return group;
}
